# --- Custom Exceptions ---
class CharactersRAGDBError(Exception):
    """Base exception for CharactersRAGDB related errors."""
    pass


class SchemaError(CharactersRAGDBError):
    """Exception for schema version mismatches or migration failures."""
    pass


class InputError(ValueError):
    """Custom exception for input validation errors."""
    pass


class ConflictError(CharactersRAGDBError):
    """
    Indicates a conflict due to concurrent modification or unique constraint violation.

    This can occur if a record's version doesn't match an expected version during
    an update/delete operation (optimistic locking), or if an insert/update
    violates a unique constraint (e.g., duplicate name).

    Attributes:
        entity (Optional[str]): The type of entity involved in the conflict (e.g., "character_cards").
        entity_id (Any): The ID or unique identifier of the entity involved.
    """

    def __init__(
        self,
        message: str = "Conflict detected.",
        entity: str | None = None,
        entity_id: Any = None,
        identifier: Any = None,
    ):
        super().__init__(message)
        if entity_id is None and identifier is not None:
            entity_id = identifier
        self.entity = entity
        self.entity_id = entity_id

    def __str__(self):
        base = super().__str__()
        details = []
        if self.entity:
            details.append(f"Entity: {self.entity}")
        if self.entity_id:
            details.append(f"ID: {self.entity_id}")
        return f"{base} ({', '.join(details)})" if details else base


class OwnerScopeRequiredError(CharactersRAGDBError):
    """A PostgreSQL owner-scoped helper was called with no owner and no opt-out."""

    def __init__(self, helper: str, table: str):
        super().__init__(f"{helper} needs an owner on PostgreSQL (table {table})")


class OwnerScope(enum.Enum):
    """Explicit opt-out from owner scoping on PostgreSQL.

    NOT_APPLICABLE: the table has no tenant ``client_id``, or a parent lock taken
    with the owner in this transaction already proved ownership.
    """

    NOT_APPLICABLE = "not_applicable"


def _owner_is_scoped(backend_type: Any, owner_client_id: str | OwnerScope | None, helper: str, table: str) -> bool:
    """Say whether to apply an owner predicate; raise on PostgreSQL when none was given."""
    if backend_type != BackendType.POSTGRESQL or owner_client_id is OwnerScope.NOT_APPLICABLE:
        return False
    if owner_client_id is None:
        raise OwnerScopeRequiredError(helper, table)
    return True


