    @staticmethod
    def _path_is_within(path: Path, base: Path) -> bool:
        try:
            path.relative_to(base)
            return True
        except ValueError:
            return False

    @classmethod
    def _sqlite_allowed_roots(cls) -> tuple[Path, ...]:
        roots: list[Path] = [Path(tempfile.gettempdir()).resolve(strict=False), Path.cwd().resolve(strict=False)]
        try:
            roots.append(DatabasePaths.get_user_db_base_dir().resolve(strict=False))
        except _CHACHA_NONCRITICAL_EXCEPTIONS:
            pass

        unique_roots: list[Path] = []
        seen: set[str] = set()
        for root in roots:
            marker = str(root)
            if marker in seen:
                continue
            seen.add(marker)
            unique_roots.append(root)
        return tuple(unique_roots)

    @classmethod
    def _resolve_sqlite_db_path(cls, db_path: str | Path) -> tuple[bool, Path]:
        if isinstance(db_path, Path):
            raw_path = db_path
            is_memory = False
        else:
            raw_text = str(db_path).strip()
            is_memory = raw_text == ":memory:"
            raw_path = Path(raw_text) if raw_text else Path(str(db_path))

        if is_memory:
            return True, Path(":memory:")

        raw_text = str(raw_path)
        if "\x00" in raw_text:
            raise CharactersRAGDBError("Database path contains invalid null byte.")

        candidate = raw_path.expanduser()
        if not candidate.is_absolute():
            candidate = Path.cwd() / candidate
        resolved_path = candidate.resolve(strict=False)

        allowed_roots = cls._sqlite_allowed_roots()
        if not any(cls._path_is_within(resolved_path, root) for root in allowed_roots):
            allowed_display = ", ".join(str(root) for root in allowed_roots)
            raise CharactersRAGDBError(
                f"Database path must be under an approved root directory: {allowed_display}"
            )
        return False, resolved_path

    def __init__(
        self,
        db_path: str | Path,
        client_id: str,
        *,
        backend: DatabaseBackend | None = None,
        config: ConfigParser | None = None,
        owner_user_id: str | None = None,
        require_existing_sqlite: bool = False,
    ) -> None:
        """
        Initializes the CharactersRAGDB instance.

        Sets up the database path, client ID, and ensures the schema is
        initialized or migrated to the current version (_CURRENT_SCHEMA_VERSION).

        Args:
            db_path: Path to the SQLite database file (e.g., "data/app.db")
                     or ":memory:" for an in-memory database.
            client_id: A unique identifier for this client instance. Used for
                       tracking changes in the sync log and records. Must not be empty.
            owner_user_id: Canonical owner supplied by trusted dependency construction,
                           never request metadata. Defaults to the initial client_id
                           for standalone callers that already use it as their owner.
            require_existing_sqlite: Open file-backed SQLite with ``mode=rw`` so
                                     construction cannot create a missing database.

        Raises:
            ValueError: If `client_id` is empty or None.
            CharactersRAGDBError: If database directory creation fails, or if
                                  database initialization/schema setup encounters
                                  a critical error.
            SchemaError: If schema migration or versioning issues occur.
        """
        is_memory, resolved_path = self._resolve_sqlite_db_path(db_path)

        self.is_memory_db = is_memory
        self.db_path = resolved_path
        self.db_path_str = ':memory:' if self.is_memory_db else str(self.db_path)

        if not client_id:
            raise ValueError("Client ID cannot be empty or None.")  # noqa: TRY003
        if not isinstance(require_existing_sqlite, bool):
            raise ValueError("require_existing_sqlite must be a boolean.")  # noqa: TRY003
        self.client_id = client_id
        self._owner_user_id = str(client_id if owner_user_id is None else owner_user_id)
        self._require_existing_sqlite = require_existing_sqlite
        self._local = threading.local()
        self._schema_lock = threading.RLock()
        self._bootstrapped_backend_targets: set[str] = set()
        self._backend_refresh_suspended = False
        # Ownership marker for backend lifecycle:
        # - True: this wrapper directly owns the backend lifecycle and cleanup.
        # - False: lifecycle is managed externally (factory-managed shared backend or injected backend).
        self._owner_managed_backend = False
        self._uses_shared_content_backend = False
        self._backend, self._uses_shared_content_backend = self._resolve_backend(
            backend=backend,
            config=config,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.character_store import (
            CharacterStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.chat_import_store import ChatImportStore
        from tldw_Server_API.app.core.DB_Management.chacha.conversation_resume_store import (
            ConversationResumeStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.conversation_store import (
            ConversationStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.keyword_store import (
            KeywordStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.message_store import (
            MessageStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.moodboard_sync_store import (
            MoodboardSyncStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.native_chat_asset_store import NativeChatAssetStore
        from tldw_Server_API.app.core.DB_Management.chacha.native_fork_store import NativeForkStore
        from tldw_Server_API.app.core.DB_Management.chacha.note_attachment_store import (
            NoteAttachmentStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.note_graph_projection_store import (
            NoteGraphProjectionStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.note_graph_suggestion_store import (
            NoteGraphSuggestionStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.note_link_store import NotesLinkStore
        from tldw_Server_API.app.core.DB_Management.chacha.note_provenance_store import NoteProvenanceStore
        from tldw_Server_API.app.core.DB_Management.chacha.note_semantic_store import NoteSemanticStore
        from tldw_Server_API.app.core.DB_Management.chacha.note_store import NoteStore
        from tldw_Server_API.app.core.DB_Management.chacha.persona_state_store import (
            PersonaStateStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.shared_workspace_chat_store import (
            SharedWorkspaceChatStore,
        )
        from tldw_Server_API.app.core.DB_Management.chacha.task_store import TaskStore
        from tldw_Server_API.app.core.DB_Management.chacha.workspace_chat_startup_store import WorkspaceChatStartupStore

        ctx = self.ctx  # one context, built before the stores that share it
        self.character_store = CharacterStore(self)
        self.conversation_store = ConversationStore(ctx)
        self.native_forks = NativeForkStore(self)
        self.workspace_chat_startups = WorkspaceChatStartupStore(self)
        self.native_assets = NativeChatAssetStore(self)
        self.conversation_resume_store = ConversationResumeStore(self)
        self.message_store = MessageStore(ctx)
        self.chat_imports = ChatImportStore(self)
        self.note_store = NoteStore(ctx)
        self.note_provenance_store = NoteProvenanceStore(self)
        self.moodboard_sync_store = MoodboardSyncStore(self)
        self.note_attachment_store = NoteAttachmentStore(self)
        self.notes_link_store = NotesLinkStore(self)
        self.note_graph_projection_store = NoteGraphProjectionStore(self)
        self.note_graph_suggestion_store = NoteGraphSuggestionStore(self)
        self.note_semantic_store = NoteSemanticStore(self)
        self.task_store = TaskStore(self)
        self.keyword_store = KeywordStore(ctx)
        self.persona_state_store = PersonaStateStore(self)
        from tldw_Server_API.app.core.DB_Management.chacha.persona_transcript_store import PersonaTranscriptStore
        self.persona_transcript_store = PersonaTranscriptStore(self)
        self.shared_workspace_chat_store = SharedWorkspaceChatStore(self)

        if self.backend_type != BackendType.SQLITE:
            self.is_memory_db = False

        if self.backend_type == BackendType.SQLITE and not self.is_memory_db:
            if self._require_existing_sqlite and not self.db_path.is_file():
                raise CharactersRAGDBError(  # noqa: TRY003
                    "Existing SQLite database is required."
                )
            db_parent = self.db_path.parent.resolve(strict=False)
            allowed_roots = self._sqlite_allowed_roots()
            if not any(self._path_is_within(db_parent, root) for root in allowed_roots):
                raise CharactersRAGDBError(  # noqa: TRY003
                    f"Rejected SQLite directory outside approved roots: {db_parent}"
                )
            try:
                db_parent.mkdir(parents=True, exist_ok=True)
            except OSError as e:
                raise CharactersRAGDBError(  # noqa: TRY003
                    f"Failed to create database directory {db_parent}: {e}"
                ) from e

        logger.info(
            f"Initializing CharactersRAGDB for path: {self.db_path_str} "
            f"[Client ID: {self.client_id}] (backend={self.backend_type.value})"
        )
        try:
            self._initialize_schema()
            self._mark_backend_bootstrapped(self._backend)
            if self._owner_managed_backend and self.backend_type == BackendType.SQLITE and not self.is_memory_db:
                # File bootstrap owns this checkout; runtime work opens its own.
                self.close_connection()
            logger.debug(f"CharactersRAGDB initialization completed successfully for {self.db_path_str}")
        except (CharactersRAGDBError, sqlite3.Error) as e:
            logger.critical(f"FATAL: DB Initialization failed for {self.db_path_str}: {e}", exc_info=True)
            self.close_connection()  # Attempt to clean up
            raise CharactersRAGDBError(f"Database initialization failed: {e}") from e  # noqa: TRY003
        except _CHACHA_NONCRITICAL_EXCEPTIONS as e:
            logger.critical(f"FATAL: Unexpected error during DB Initialization for {self.db_path_str}: {e}",
                            exc_info=True)
            self.close_connection()
            raise CharactersRAGDBError(f"Unexpected database initialization error: {e}") from e  # noqa: TRY003

    @property
    def owner_user_id(self) -> str:
        """Return construction-time ownership, independent of writer attribution."""
        return self._owner_user_id

    @cached_property
    def ctx(self) -> ChaChaContext:
        """The stores' shared context (R19). Lazy, so a DB built with ``__new__`` reaches it too."""
        from tldw_Server_API.app.core.DB_Management.chacha.context import ChaChaContext

        return ChaChaContext(self)

    # --- Backend Resolution Helpers ---
    def _resolve_backend(
        self,
        *,
        backend: DatabaseBackend | None,
        config: ConfigParser | None,
    ) -> tuple[DatabaseBackend, bool]:
        """Select the database backend instance for this content store."""
        if backend is not None:
            self._owner_managed_backend = False
            return backend, False

        parser: ConfigParser | None = config
        if parser is None:
            try:
                parser = load_comprehensive_config()
            except _CHACHA_NONCRITICAL_EXCEPTIONS:
                parser = None

        if parser is not None:
            candidate = get_content_backend(parser)
            if candidate and candidate.backend_type == BackendType.POSTGRESQL:
                self._owner_managed_backend = False
                return candidate, True

        sqlite_path = self.db_path_str
        if self._require_existing_sqlite and not self.is_memory_db:
            sqlite_path = f"{self.db_path.as_uri()}?mode=rw"
        fallback_config = DatabaseConfig(
            backend_type=BackendType.SQLITE,
            sqlite_path=sqlite_path,
        )
        if not self.is_memory_db:
            # Contract: default file-backed SQLite for CharactersRAGDB is intentionally
            # isolated from the global factory registry. This wrapper owns cleanup for
            # that backend and it is not affected by factory-wide reset/close calls.
            self._owner_managed_backend = True
            return SQLiteBackend(fallback_config), False
        self._owner_managed_backend = False
        return DatabaseBackendFactory.create_backend(fallback_config), False

    def _backend_target_key(self, backend: DatabaseBackend | None) -> str | None:
        if backend is None:
            return None
        config = getattr(backend, "config", None)
        if backend.backend_type == BackendType.POSTGRESQL:
            if config and getattr(config, "connection_string", None):
                return str(config.connection_string)
            if config:
                host = getattr(config, "pg_host", None) or "localhost"
                port = getattr(config, "pg_port", None) or 5432
                database = getattr(config, "pg_database", None) or "<postgres>"
                return f"{host}:{port}/{database}"
            return f"postgres:{id(backend)}"
        if config and getattr(config, "sqlite_path", None):
            return str(config.sqlite_path)
        return f"sqlite:{id(backend)}"

    def _connection_state(self) -> Any:
        """Use an explicit PostgreSQL operation, retaining legacy/SQLite state."""
        if self._backend.backend_type == BackendType.POSTGRESQL:
            state = current_connection_state(self)
            if state is not None:
                return state
        return self._local

    def _get_pinned_backend(self) -> DatabaseBackend | None:
        return getattr(self._connection_state(), "backend_ref", None)

    def _mark_backend_bootstrapped(self, backend: DatabaseBackend | None) -> None:
        key = self._backend_target_key(backend)
        if key:
            self._bootstrapped_backend_targets.add(key)

    def _ensure_bootstrap_for_backend(self, backend: DatabaseBackend) -> None:
        if backend.backend_type != BackendType.POSTGRESQL:
            return
        key = self._backend_target_key(backend)
        if key in self._bootstrapped_backend_targets:
            return
        previous_suspend = self._backend_refresh_suspended
        self._backend_refresh_suspended = True
        try:
            self._backend = backend
            self._initialize_schema()
        finally:
            self._backend_refresh_suspended = previous_suspend
        if key:
            self._bootstrapped_backend_targets.add(key)

    @property
    def backend(self) -> DatabaseBackend:
        pinned_backend = self._get_pinned_backend()
        if pinned_backend is not None:
            return pinned_backend
        if not self._uses_shared_content_backend:
            return self._backend
        if self._backend_refresh_suspended:
            return self._backend
        with self._schema_lock:
            pinned_backend = self._get_pinned_backend()
            if pinned_backend is not None:
                return pinned_backend
            if not self._uses_shared_content_backend:
                return self._backend
            if self._backend_refresh_suspended:
                return self._backend

            current_key = self._backend_target_key(self._backend)
            refreshed_backend, uses_shared_backend = self._resolve_backend(backend=None, config=None)
            self._uses_shared_content_backend = uses_shared_backend
            self._backend = refreshed_backend
            refreshed_key = self._backend_target_key(refreshed_backend)
            if (
                uses_shared_backend
                and refreshed_backend.backend_type == BackendType.POSTGRESQL
                and refreshed_key != current_key
            ):
                self._ensure_bootstrap_for_backend(refreshed_backend)
            return self._backend

    @property
    def backend_type(self) -> BackendType:
        return self.backend.backend_type

    @overload
    def _prepare_backend_statement(
        self,
        query: str,
        params: tuple | dict,
    ) -> tuple[str, tuple | dict]: ...

    @overload
    def _prepare_backend_statement(
        self,
        query: str,
        params: tuple | list | dict | None = None,
    ) -> tuple[str, tuple | list | dict | None]: ...

    def _prepare_backend_statement(
        self,
        query: str,
        params: tuple | list | dict | None = None,
    ) -> tuple[str, tuple | list | dict | None]:
        return self.ctx.prepare_statement(query, params)

    def _prepare_backend_many_statement(
        self,
        query: str,
        params_list: Sequence[tuple | list | dict],
    ) -> tuple[str, list[tuple | list | dict]]:
        converted_query, prepared_params = prepare_backend_many_statement(
            self.backend_type,
            query,
            params_list,
            transformer=self._transform_query_for_backend
            if self.backend_type == BackendType.POSTGRESQL
            else None,
            ensure_returning=False,
        )
        return converted_query, prepared_params

    def _normalise_params(
        self,
        params: list | tuple | dict | Any | None,
    ) -> tuple | dict | None:
        return normalise_params(params)

    def _transform_query_for_backend(self, query: str) -> str:
        if self.backend_type != BackendType.POSTGRESQL:
            return query
        return transform_sqlite_query_for_postgres(query)

    def _open_new_connection(self, backend: DatabaseBackend | None = None) -> RawBackendConnection:
        _return_dropped_checkouts()
        active_backend = backend or self.backend
        try:
            pool = active_backend.get_pool()
            conn: RawBackendConnection = pool.get_connection()
            # Apply per-tenant session guard for PostgreSQL (RLS via current_setting('app.current_user_id'))
            if active_backend.backend_type == BackendType.POSTGRESQL and self.client_id:
                conn = self._apply_postgres_client_scope(conn, pool)
            return conn  # noqa: TRY300
        except BackendDatabaseError as exc:
            raise CharactersRAGDBError(f"Failed to acquire database connection: {exc}") from exc  # noqa: TRY003

    def _apply_postgres_client_scope(
        self,
        conn: RawBackendConnection,
        pool,
    ) -> RawBackendConnection:
        """Best-effort helper to set session-scoped client_id in PostgreSQL.

        Ensures failed SET/COMMIT attempts do not leave pooled connections in a
        broken transaction state by rolling back (or replacing) the connection.
        """
        user_value = str(self.client_id)

        def _set_session(target) -> None:
            cur = target.cursor()
            if psycopg_sql is not None:
                statement = psycopg_sql.SQL(
                    "SELECT set_config('app.current_user_id', {}, false)"
                ).format(psycopg_sql.Literal(user_value))
                cur.execute(statement)
            else:
                cur.execute(
                    "SELECT set_config('app.current_user_id', %s, false)",
                    (user_value,),
                )

        def _replace_connection(bad_conn: RawBackendConnection) -> RawBackendConnection:
            with contextlib.suppress(*_CHACHA_NONCRITICAL_EXCEPTIONS):
                bad_conn.close()
            with contextlib.suppress(*_CHACHA_NONCRITICAL_EXCEPTIONS):
                pool.return_connection(bad_conn)
            replacement: RawBackendConnection = pool.get_connection()
            return replacement

        def _safe_rollback(target, context: str) -> bool:
            try:
                target.rollback()
                return True  # noqa: TRY300
            except _CHACHA_NONCRITICAL_EXCEPTIONS as rollback_exc:  # noqa: BLE001
                logger.warning(
                    'Rollback failed after {} while setting PostgreSQL session scope: {}',
                    context,
                    rollback_exc,
                )
                return False

        try:
            _set_session(conn)
            try:
                conn.commit()
            except _CHACHA_NONCRITICAL_EXCEPTIONS as commit_exc:  # noqa: BLE001
                logger.warning(
                    'Commit failed after setting PostgreSQL session scope; attempting rollback: {}',
                    commit_exc,
                )
                if not _safe_rollback(conn, "commit failure"):
                    conn = _replace_connection(conn)
                    try:
                        _set_session(conn)
                        conn.commit()
                    except _CHACHA_NONCRITICAL_EXCEPTIONS as retry_exc:  # noqa: BLE001
                        logger.warning(
                            'Retrying PostgreSQL session scope setup failed: {}',
                            retry_exc,
                        )
                        _safe_rollback(conn, "retry failure")
        except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:  # noqa: BLE001
            logger.warning(
                'Failed to set PostgreSQL session scope; attempting rollback: {}',
                exc,
            )
            if not _safe_rollback(conn, "SET failure"):
                conn = _replace_connection(conn)
                try:
                    _set_session(conn)
                    conn.commit()
                except _CHACHA_NONCRITICAL_EXCEPTIONS as retry_exc:  # noqa: BLE001
                    logger.warning(
                        'Retrying PostgreSQL session scope setup failed: {}',
                        retry_exc,
                    )
                    _safe_rollback(conn, "retry failure")
        return conn

    def _release_connection(
        self,
        connection: RawBackendConnection,
        backend: DatabaseBackend | None = None,
    ) -> None:
        active_backend = backend or self._get_pinned_backend() or self._backend
        try:
            if active_backend.backend_type == BackendType.SQLITE:
                thread_id = threading.get_ident()
                try:
                    pool = active_backend.get_pool()
                    pool._connections[thread_id] = None  # type: ignore[attr-defined]
                    if hasattr(pool._local, 'connection'):  # type: ignore[attr-defined]
                        pool._local.connection = None  # type: ignore[attr-defined]
                except AttributeError:
                    pass
                with contextlib.suppress(sqlite3.Error):
                    connection.close()
            else:
                active_backend.get_pool().return_connection(connection)
        except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:  # noqa: BLE001
            logger.warning("Error while releasing connection: {}", exc)

    # --- Connection Management ---
    def _get_thread_connection(self) -> Any:
        """
        Retrieve (or open) the thread-local connection for the configured backend.

        For SQLite we maintain a single `sqlite3.Connection` per thread and ensure it
        stays usable (re-opening on failure). For PostgreSQL we borrow a pooled
        connection owned by the active operation, or by the legacy thread when
        no operation was established.

        Returns:
            Backend-specific connection handle suitable for use with
            :class:`BackendConnectionWrapper`.

        Raises:
            CharactersRAGDBError: If acquiring a connection from the backend fails.
        """
        state = self._connection_state()
        with getattr(state, 'allocation_lock', contextlib.nullcontext()):
            return self._get_connection_for_state(state)

    def _get_connection_for_state(self, state: Any) -> Any:
        conn = getattr(state, 'conn', None)
        backend = self._get_pinned_backend() or self.backend

        if backend.backend_type == BackendType.SQLITE:
            pool = backend.get_pool()
            if conn is not None:
                try:
                    conn.execute("SELECT 1")
                    return conn  # noqa: TRY300
                except (sqlite3.ProgrammingError, sqlite3.OperationalError):
                    logger.warning(
                        'Thread-local connection for {} was closed or became unusable. Reopening.',
                        self.db_path_str,
                    )
                    try:
                        conn.close()
                    except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:  # noqa: BLE001
                        logger.warning("Failed to close database connection: {}", exc)
                    try:
                        # Prefer public helper to clear thread-local connection state
                        if hasattr(pool, 'clear_thread_local_connection'):
                            pool.clear_thread_local_connection()
                    except _CHACHA_NONCRITICAL_EXCEPTIONS:
                        # Best-effort; ignore if pool doesn't expose the helper
                        pass
                    conn = None
                    state.conn = None

            if conn is None:
                conn = self._open_new_connection(backend)
                state.conn = conn
                logger.debug(
                    'Opened/Reopened SQLite connection to {} for thread {}',
                    self.db_path_str,
                    threading.get_ident(),
                )
            return conn

        # Non-SQLite backend: reuse connection if still open, otherwise borrow anew.
        if conn is not None and getattr(conn, "closed", False):
            if getattr(state, "borrowed", False):
                raise CharactersRAGDBError("The borrowed database connection is closed")
            self._release_connection(conn, backend=backend)
            _disarm_legacy_checkout(state)
            conn = None
            state.conn = None
            state.backend_ref = None
            backend = self.backend

        if conn is None:
            conn = self._open_new_connection(backend)
            state.conn = conn
            state.backend_ref = backend
            if state is self._local:
                state.checkout_guard = _LegacyCheckout(conn, backend)
            logger.debug(
                'Acquired backend connection ({}) for thread {}',
                backend.backend_type.value,
                threading.get_ident(),
            )
        return conn

    @_owned_database_call
    def get_connection(self) -> Any:
        """Return the active connection wrapper for the current thread."""
        raw_conn = self._get_thread_connection()
        backend = self._get_pinned_backend() or self.backend
        if backend.backend_type == BackendType.SQLITE:
            return raw_conn
        return BackendConnectionWrapper(self, raw_conn, backend)

    def close_connection(self):
        """
        Closes the current thread's database connection.

        If the database is file-based and in WAL mode, it attempts to perform
        a WAL checkpoint (TRUNCATE) before closing to commit changes from the WAL file
        to the main database file.
        If a transaction is active and uncommitted on this connection, it attempts a rollback.
        Clears the connection reference from `threading.local` for the current thread.
        """
        _return_dropped_checkouts()
        state = self._connection_state()
        if state is not self._local:
            state.release()
            return
        conn = getattr(self._local, 'conn', None)
        if conn is None:
            return
        backend = self._get_pinned_backend() or self._backend

        try:
            if backend.backend_type == BackendType.SQLITE:
                if not self.is_memory_db:
                    if conn.in_transaction:
                        try:
                            logger.warning(
                                'Connection to {} is in an uncommitted transaction during close. Attempting rollback.',
                                self.db_path_str,
                            )
                            conn.rollback()
                        except sqlite3.Error as rb_err:
                            logger.error(
                                'Rollback attempt during close for {} failed: {}',
                                self.db_path_str,
                                rb_err,
                            )

                    if not conn.in_transaction:
                        mode_row = conn.execute("PRAGMA journal_mode;").fetchone()
                        if mode_row and mode_row[0].lower() == 'wal':
                            try:
                                logger.debug(
                                    'Attempting WAL checkpoint (TRUNCATE) before closing {} on thread {}.',
                                    self.db_path_str,
                                    threading.get_ident(),
                                )
                                conn.execute("PRAGMA wal_checkpoint(TRUNCATE);")
                                logger.debug("WAL checkpoint TRUNCATE executed for {}.", self.db_path_str)
                            except sqlite3.Error as cp_err:
                                logger.warning("WAL checkpoint failed for {}: {}", self.db_path_str, cp_err)

                conn.close()
                logger.debug(
                    'Closed SQLite connection for thread {} to {}.',
                    threading.get_ident(),
                    self.db_path_str,
                )
            else:
                _disarm_legacy_checkout(self._local)
                backend.get_pool().return_connection(conn)
                logger.debug(
                    'Returned backend connection ({}) for thread {}.',
                    backend.backend_type.value,
                    threading.get_ident(),
                )
        except sqlite3.Error as exc:
            logger.warning(
                'Error during SQLite connection close/checkpoint for {} on thread {}: {}',
                self.db_path_str,
                threading.get_ident(),
                exc,
            )
        finally:
            if hasattr(self._local, 'conn'):
                self._local.conn = None
            if hasattr(self._local, 'backend_ref'):
                self._local.backend_ref = None
            if backend.backend_type == BackendType.SQLITE:
                try:
                    pool = backend.get_pool()
                    if hasattr(pool, 'clear_thread_local_connection'):
                        pool.clear_thread_local_connection()
                except _CHACHA_NONCRITICAL_EXCEPTIONS:
                    pass

    def _discard_legacy_checkout(self) -> None:
        """Close this thread's legacy PostgreSQL checkout instead of queuing its return."""
        conn = getattr(self._local, "conn", None) if self._connection_state() is self._local else None
        if conn is None:
            self.close_connection()
            return
        backend = self._get_pinned_backend() or self._backend
        self._local.conn = None
        self._local.backend_ref = None
        _disarm_legacy_checkout(self._local)
        backend.get_pool().discard_connection(conn)

    def close_all_connections(self) -> None:
        """
        Force-close all backend connections managed by this instance.

        Primarily used in tests/shutdown to ensure no background SQLite threads remain.
        On PostgreSQL the shared content pool is never closed here: every user's
        handle draws from it, and content-backend shutdown owns it. Other threads'
        checkouts are left to those threads, which close them on their own exit.
        """
        if self.backend_type == BackendType.POSTGRESQL:
            if self._uses_shared_content_backend:
                self.close_connection()
                return
            # The caller's pool is closed below. putconn hands a checkout to a pool
            # worker for its reset, and a pool closed first discards that work, leaving
            # the connection open and unreset, so close this thread's checkout now.
            self._discard_legacy_checkout()
        else:
            self.close_connection()

        if (
            self.backend_type == BackendType.SQLITE
            and is_factory_managed_backend(self.backend)
        ):
            release_managed_backend(self.backend)
            with contextlib.suppress(*_CHACHA_NONCRITICAL_EXCEPTIONS):
                self._local = threading.local()
            return

        try:
            pool = self.backend.get_pool()
        except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:  # noqa: BLE001
            logger.warning("Unable to retrieve backend pool while closing connections: {}", exc)
            pool = None

        if self.backend_type == BackendType.SQLITE and pool is not None:
            close_all = getattr(pool, "close_all", None)
            if callable(close_all):
                try:
                    close_all()
                except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:  # noqa: BLE001
                    logger.warning("Error closing all SQLite connections for {}: {}", self.db_path_str, exc)
        elif pool is not None:
            try:
                pool.close_all()
            except AttributeError:
                pass
            except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:  # noqa: BLE001
                logger.warning("Error closing all backend connections for {}: {}", self.db_path_str, exc)


        # Reset the thread-local reference, except on PostgreSQL: replacing it would drop every
        # other thread's slot here, while those threads may be inside libpq on their checkouts.
        # Each guard stays in its own slot and is finalized on its own thread instead.
        if self.backend_type != BackendType.POSTGRESQL:
            with contextlib.suppress(*_CHACHA_NONCRITICAL_EXCEPTIONS):
                self._local = threading.local()

    def backup_database(self, backup_file_path: str) -> bool:
        """
        Creates a backup of the current database to the specified file path.

        Args:
            backup_file_path (str): The path to save the backup database file.

        Returns:
            bool: True if the backup was successful, False otherwise.
        """
        logger.info(f"Starting database backup from '{self.db_path_str}' to '{backup_file_path}'")
        # src_conn is managed by get_connection and should not be closed by this method directly
        # backup_conn is local to this method and must be closed
        backup_conn: sqlite3.Connection | None = None
        try:
            # Ensure the backup file path is not the same as the source for file-based DBs
            if not self.is_memory_db and self.db_path.resolve() == Path(backup_file_path).resolve():
                logger.error("Backup path cannot be the same as the source database path.")
                raise ValueError("Backup path cannot be the same as the source database path.")  # noqa: TRY003, TRY301

            src_conn = self.get_connection()

            # Ensure parent directory for backup_file_path exists
            backup_db_path_obj = Path(backup_file_path)
            backup_db_path_obj.parent.mkdir(parents=True, exist_ok=True)

            backup_conn = sqlite3.connect(str(backup_db_path_obj)) # Use string path for connect

            logger.debug(f"Source DB connection: {src_conn}")
            logger.debug(f"Backup DB connection: {backup_conn} to file {str(backup_db_path_obj)}")

            # Perform the backup
            src_conn.backup(backup_conn, pages=0, progress=None)

            logger.info(f"Database backup successful from '{self.db_path_str}' to '{str(backup_db_path_obj)}'")
            return True  # noqa: TRY300
        except ValueError as ve: # Catch specific ValueError for path mismatch first
            logger.error(f"ValueError during database backup: {ve}", exc_info=True)
            return False
        except sqlite3.Error as e:
            logger.error(f"SQLite error during database backup: {e}", exc_info=True)
            return False
        except _CHACHA_NONCRITICAL_EXCEPTIONS as e:
            logger.error(f"Unexpected error during database backup: {e}", exc_info=True)
            return False
        finally:
            if backup_conn:
                try:
                    backup_conn.close()
                    logger.debug("Closed backup database connection.")
                except sqlite3.Error as e:
                    logger.warning(f"Error closing backup database connection: {e}")
            # Source connection (src_conn) is managed by the thread-local mechanism
            # and should not be closed here to allow continued use of the DB instance.

    # --- Query Execution ---
    @_owned_database_call
    def execute_query(
        self,
        query: str,
        params: tuple | dict[str, Any] | None = None,
        *,
        commit: bool = False,
        script: bool = False,
        log_params: bool = True,
        log_errors: bool = True,
        read_only: bool = False,
    ) -> Any:
        """
        Executes a single SQL query or an entire SQL script.

        Args:
            query: The SQL query string or script.
            params: Optional parameters for the query (tuple or dict).
                    Not used if `script` is True. Defaults to None.
            commit: If True, and not within an explicit transaction context managed
                    by `with db.transaction():`, commits the transaction after execution.
                    Defaults to False.
            script: If True, executes the query string as an SQL script using `executescript`.
                    `params` are ignored if `script` is True. Defaults to False.
            log_params: Whether debug logs may include bounded parameter values.
                    Sensitive query paths set this to False. Defaults to True.
            log_errors: Whether driver errors may be logged verbatim. Sensitive
                    source reads set this to False. Defaults to True.
            read_only: Opt in a known side-effect-free read to completing its own
                    PostgreSQL transaction. Pre-existing or explicitly managed
                    transactions and SQLite are unchanged. Defaults to False.

        Returns:
            The sqlite3.Cursor object after execution.

        Raises:
            ConflictError: If an SQLite IntegrityError due to a "unique constraint failed" occurs.
            CharactersRAGDBError: For other SQLite errors or general query execution failures.
        """
        conn = self.get_connection()
        read_scope: contextlib.AbstractContextManager[Any] = contextlib.nullcontext()
        if read_only and self.backend_type == BackendType.POSTGRESQL:
            raw_conn = conn._connection
            backend = conn._backend
            status = getattr(getattr(raw_conn, "info", None), "transaction_status", None)
            if (
                getattr(status, "name", None) == "IDLE"
                and getattr(self._connection_state(), "tx_depth", 0) == 0
                and backend._tx_depth(raw_conn) == 0
            ):
                # Own only this new read; never settle an existing caller's work.
                read_scope = backend.transaction(connection=raw_conn)
        try:
            logger.debug(
                'Executing SQL (script={}, backend={}): {}... Params: {}...',
                script,
                self.backend_type.value,
                query[:300],
                str(params)[:200] if log_params else "[redacted]",
            )

            with read_scope:
                if script:
                    if self.backend_type == BackendType.SQLITE:
                        cursor = conn.executescript(query)
                    else:
                        cursor = conn.executescript(query, log_errors=log_errors)
                else:
                    prepared_query, prepared_params = self._prepare_backend_statement(query, params)
                    if self.backend_type == BackendType.SQLITE:
                        cursor = conn.cursor()
                    else:
                        cursor = conn.cursor(log_errors=log_errors)
                    cursor.execute(prepared_query, prepared_params or ())

            if commit:
                try:
                    if self.backend_type == BackendType.SQLITE:
                        if not conn.in_transaction:
                            conn.commit()
                            logger.debug("Committed directly by execute_query.")
                    else:
                        conn.commit()
                except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:
                    if not log_errors:
                        logger.error(
                            'Redacted commit failure after execute_query ({})',
                            type(exc).__name__,
                        )
                        raise CharactersRAGDBError("Database commit failed.") from None
                    logger.error(
                        'Commit failed after execute_query on backend {}: {}',
                        self.backend_type.value,
                        exc,
                        exc_info=True,
                    )
                    raise CharactersRAGDBError(f"Database commit failed: {exc}") from exc  # noqa: TRY003
            return cursor  # noqa: TRY300
        except sqlite3.IntegrityError as e:
            if not log_errors:
                logger.warning("Redacted SQLite integrity failure ({})", type(e).__name__)
                raise CharactersRAGDBError("Database constraint violation.") from None
            logger.warning(f"Integrity constraint violation: {query[:300]}... Error: {e}")
            # Distinguish unique constraint from other integrity errors if possible
            if "unique constraint failed" in str(e).lower():
                raise ConflictError(message=f"Unique constraint violation: {e}") from e
            raise CharactersRAGDBError(  # noqa: TRY003
                f"Database constraint violation: {e}") from e  # Broader for other integrity issues
        except sqlite3.Error as e:
            if not log_errors:
                logger.error("Redacted SQLite query failure ({})", type(e).__name__)
                raise CharactersRAGDBError("Query execution failed.") from None
            logger.error(f"Query execution failed: {query[:300]}... Error: {e}", exc_info=True)
            raise CharactersRAGDBError(f"Query execution failed: {e}") from e  # noqa: TRY003
        except BackendDatabaseError as exc:
            if not log_errors:
                logger.error("Redacted backend query failure ({})", type(exc).__name__)
                raise CharactersRAGDBError("Query execution failed.") from None
            msg = str(exc).lower()
            if "duplicate key" in msg or "unique constraint" in msg:
                raise ConflictError(message=f"Database constraint violation: {exc}") from exc
            logger.error(
                'Backend query execution failed ({}): {}',
                self.backend_type.value,
                exc,
                exc_info=True,
            )
            raise CharactersRAGDBError(f"Query execution failed: {exc}") from exc  # noqa: TRY003

    def upsert_voice_command(
        self,
        *,
        command_id: str,
        user_id: int,
        persona_id: str | None,
        connection_id: str | None,
        name: str,
        phrases: list[str] | str,
        action_type: str,
        action_config: dict[str, Any] | str,
        priority: int,
        enabled: bool,
        requires_confirmation: bool,
        description: str | None,
        created_at: str,
        updated_at: str,
    ) -> None:
        """Persist a user-defined voice command for VoiceAssistant helpers."""
        phrases_json = phrases if isinstance(phrases, str) else json.dumps(phrases)
        action_config_json = (
            action_config if isinstance(action_config, str) else json.dumps(action_config)
        )
        self.execute_query(
            """
            INSERT INTO voice_commands (
                id, user_id, persona_id, connection_id, name, phrases,
                action_type, action_config, priority, enabled,
                requires_confirmation, description, created_at, updated_at, deleted
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
            ON CONFLICT(id) DO UPDATE SET
                user_id = excluded.user_id,
                persona_id = excluded.persona_id,
                connection_id = excluded.connection_id,
                name = excluded.name,
                phrases = excluded.phrases,
                action_type = excluded.action_type,
                action_config = excluded.action_config,
                priority = excluded.priority,
                enabled = excluded.enabled,
                requires_confirmation = excluded.requires_confirmation,
                description = excluded.description,
                updated_at = excluded.updated_at,
                deleted = 0
            """,
            (
                command_id,
                user_id,
                persona_id,
                connection_id,
                name,
                phrases_json,
                action_type,
                action_config_json,
                priority,
                1 if enabled else 0,
                1 if requires_confirmation else 0,
                description,
                created_at,
                updated_at,
            ),
            commit=True,
        )

    @_owned_database_call
    def execute_many(
        self,
        query: str,
        params_list: list[tuple],
        *,
        commit: bool = False,
    ) -> Any | None:
        """
        Executes a parameterized SQL query multiple times with a list of parameter sets.

        Args:
            query: The SQL query string.
            params_list: A list of tuples, where each tuple contains parameters for one execution.
                         If empty or invalid, the method returns None without executing.
            commit: If True, and not within an explicit transaction context,
                    commits the transaction after execution. Defaults to False.

        Returns:
            The sqlite3.Cursor object after execution, or None if params_list is empty/invalid.

        Raises:
            ConflictError: If an SQLite IntegrityError due to a "unique constraint failed" occurs during batch.
            CharactersRAGDBError: For other SQLite errors or general batch execution failures.
        """
        conn = self.get_connection()
        if not isinstance(params_list, list) or not params_list:
            logger.debug("execute_many called with empty or invalid params_list.")
            return None
        try:
            logger.debug(
                'Executing Many on backend {}: {}... with {} sets.',
                self.backend_type.value,
                query[:150],
                len(params_list),
            )
            prepared_query, prepared_params_list = self._prepare_backend_many_statement(query, params_list)
            cursor = conn.cursor()
            cursor.executemany(prepared_query, prepared_params_list)
            if commit:
                try:
                    if self.backend_type == BackendType.SQLITE:
                        if not conn.in_transaction:
                            conn.commit()
                            logger.debug("Committed Many directly by execute_many.")
                    else:
                        conn.commit()
                except _CHACHA_NONCRITICAL_EXCEPTIONS as exc:
                    logger.error(
                        'Commit failed after execute_many on backend {}: {}',
                        self.backend_type.value,
                        exc,
                        exc_info=True,
                    )
                    raise CharactersRAGDBError(f"Database commit failed: {exc}") from exc  # noqa: TRY003
            return cursor  # noqa: TRY300
        except sqlite3.IntegrityError as e:
            logger.warning(f"Integrity constraint violation during batch: {query[:150]}... Error: {e}")
            if "unique constraint failed" in str(e).lower():
                raise ConflictError(message=f"Unique constraint violation during batch: {e}") from e
            raise CharactersRAGDBError(f"Database constraint violation during batch: {e}") from e  # noqa: TRY003
        except sqlite3.Error as e:
            logger.error(f"Execute Many failed: {query[:150]}... Error: {e}", exc_info=True)
            raise CharactersRAGDBError(f"Execute Many failed: {e}") from e  # noqa: TRY003
        except BackendDatabaseError as exc:
            msg = str(exc).lower()
            if "duplicate key" in msg or "unique constraint" in msg:
                raise ConflictError(message=f"Database constraint violation during batch: {exc}") from exc
            logger.error(
                'Backend execute_many failed ({}): {}',
                self.backend_type.value,
                exc,
                exc_info=True,
            )
            raise CharactersRAGDBError(f"Execute Many failed: {exc}") from exc  # noqa: TRY003

    # --- Transaction Context ---
    def transaction(self, *, preserve_existing: bool = False) -> TransactionContextManager | BackendManagedTransaction:
        """Optionally join driver-open caller work without committing or rolling it back."""
        if self.backend_type == BackendType.SQLITE:
            return TransactionContextManager(self)
        return BackendManagedTransaction(self, preserve_existing=preserve_existing)

    # --- Schema Initialization and Migration ---
    @classmethod
    def _prepare_sqlite_schema_drift_fixture(
        cls,
        db_path: Path | str,
        *,
        version: int,
        drop_tables: tuple[str, ...],
    ) -> None:
        """Prepare a controlled SQLite schema drift fixture for migration regression tests."""
        if version < 0 or version > cls._CURRENT_SCHEMA_VERSION:
            raise ValueError(f"Unsupported schema fixture version: {version}")

        unsupported_tables = set(drop_tables) - set(cls._SQLITE_MIGRATION_FIXTURE_DROP_STATEMENTS)
        if unsupported_tables:
            raise ValueError(f"Unsupported schema fixture table drops: {sorted(unsupported_tables)}")

        with sqlite3.connect(str(db_path)) as conn:
            conn.execute("PRAGMA foreign_keys = OFF")
            conn.execute(
                "UPDATE db_schema_version SET version = ? WHERE schema_name = ?",
                (version, cls._SCHEMA_NAME),
            )
            for table_name in drop_tables:
                conn.execute(cls._SQLITE_MIGRATION_FIXTURE_DROP_STATEMENTS[table_name])
            conn.commit()

    def _sqlite_linear_migration_steps(self) -> dict[int, Callable[[sqlite3.Connection], None]]:
        """Return SQLite schema migrations keyed by their source schema version."""
        return {version: bind(getattr(sqlite_steps, name), self.ctx) for version, name in sqlite_steps.SQLITE_STEPS.items()}

    def _run_sqlite_linear_migration_step(
        self,
        conn: sqlite3.Connection,
        *,
        from_version: int,
        target_version: int,
        initial_version: int,
    ) -> int:
        steps = self._sqlite_linear_migration_steps()
        step = steps.get(from_version)
        if step is None:
            raise SchemaError(  # noqa: TRY003
                f"Migration path undefined for '{self._SCHEMA_NAME}' from version {from_version} to {target_version} "
                f"while migrating from {initial_version} to {target_version}. Manual migration or a new database may be required."
            )
        step(conn)
        next_version = sqlite_schema._get_db_version(self.ctx, conn)
        expected_version = from_version + 1
        if next_version != expected_version:
            raise SchemaError(  # noqa: TRY003
                f"SQLite migration for '{self._SCHEMA_NAME}' advanced from version {from_version} to {next_version}; "
                f"expected {expected_version} while migrating from {initial_version} to {target_version}."
            )
        return next_version

    @staticmethod
    def _sqlite_table_names(conn: sqlite3.Connection) -> set[str]:
        """Return the SQLite table names visible to a migration connection."""
        return sqlite_schema._sqlite_table_names(conn)

    @classmethod
    def _sqlite_column_names(cls, conn: sqlite3.Connection, table_name: str) -> set[str]:
        """Return column names for controlled SQLite schema introspection."""
        return sqlite_schema._sqlite_column_names(conn, table_name)

    @classmethod
    def _sqlite_index_names(cls, conn: sqlite3.Connection, table_name: str) -> set[str]:
        """Return index names for controlled SQLite schema introspection."""
        return sqlite_schema._sqlite_index_names(conn, table_name)

    def _get_db_version(self, conn: sqlite3.Connection) -> int:
        """
        Retrieves the current schema version from the `db_schema_version` table
        for the schema named `self._SCHEMA_NAME`.

        Args:
            conn: The active sqlite3.Connection.

        Returns:
            The current schema version as an integer, or 0 if the table or entry
            for `self._SCHEMA_NAME` does not exist (indicating a fresh database).

        Raises:
            SchemaError: If there is an unexpected SQL error while querying the version,
                         other than "no such table".
        """
        return sqlite_schema._get_db_version(self.ctx, conn)

